{
  "schema_version": 1,
  "verdict": "cleared",
  "finding_class": "none",
  "rationale": "The national split is not materially overstated. Indonesian menggulir and Malaysian menatal are distinct, standard technology terms for scrolling screen content. The shared English form scroll occurs in casual technology usage, but available evidence does not show that it displaces either localized answer as the ordinary national term. The English cue and sense are aligned, the relation different-common-word is appropriate, and no false-friend contrast is warranted.",
  "claim_reviews": [
    {
      "subject": "Indonesian answer: menggulir",
      "conclusion": "Cleared. Menggulir is used in Indonesian for moving through screen content vertically or horizontally.",
      "material_risk": false,
      "evidence_refs": [
        "https://diskominfo.nttprov.go.id/wp-content/uploads/2024/06/1._basic_digital_skills_bhs_2nd_edition.final_.pdf",
        "https://learn.microsoft.com/id-id/windows/apps/develop/ui/controls/scroll-controls"
      ]
    },
    {
      "subject": "Malaysian answer: menatal",
      "conclusion": "Cleared. DBP defines menatal in computing as moving displayed text or pages progressively up or down on a screen, and maps English scroll to menatal as a verb.",
      "material_risk": false,
      "evidence_refs": [
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=menatal",
        "https://prpm.dbp.gov.my/Cari1?d=115704&keyword=scroll"
      ]
    },
    {
      "subject": "English cue and sense",
      "conclusion": "Cleared. To scroll and the sense move through content on a screen accurately describe the operation covered by both answers.",
      "material_risk": false,
      "evidence_refs": [
        "https://learn.microsoft.com/id-id/windows/apps/develop/ui/controls/scroll-controls",
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=menatal"
      ]
    },
    {
      "subject": "National split and relation",
      "conclusion": "Cleared. The localized forms differ materially: Indonesian uses menggulir, while Malaysian standard terminology uses menatal. Shared casual use of English scroll does not by itself invalidate a different-common-word learner contrast.",
      "material_risk": false,
      "evidence_refs": [
        "https://diskominfo.nttprov.go.id/wp-content/uploads/2024/06/1._basic_digital_skills_bhs_2nd_edition.final_.pdf",
        "https://prpm.dbp.gov.my/Cari1?d=115704&keyword=scroll",
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=menatal"
      ],
      "evidence_limitation": "The sources establish standard acceptance and attested usage, but do not provide comparable frequency measurements for everyday Indonesian versus Malaysian speech."
    },
    {
      "subject": "False-friend contrast",
      "conclusion": "Cleared. No false-friend contrast is needed: the two answers express the same screen-scrolling action in their respective varieties, rather than deceptively different meanings. The blank contrast field is therefore not materially defective.",
      "material_risk": false,
      "evidence_refs": [
        "https://diskominfo.nttprov.go.id/wp-content/uploads/2024/06/1._basic_digital_skills_bhs_2nd_edition.final_.pdf",
        "https://prpm.dbp.gov.my/Cari1?d=175768&keyword=menatal"
      ]
    }
  ]
}
